import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/models/audio_track.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/spectrum_settings.dart';
import 'package:nothingness/models/song_info.dart';
import 'package:nothingness/models/transport_position.dart';
import 'package:nothingness/screens/void_screen.dart';
import 'package:nothingness/services/library_browser.dart';
import 'package:nothingness/services/library_service.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/theme/app_palette.dart';
import 'package:nothingness/theme/app_typography.dart';
import 'package:nothingness/widgets/hero_feedback_surface.dart';
import 'package:nothingness/widgets/heroes/_test_helpers.dart';

class _SeekUpdatingProvider extends FakeAudioPlayerProvider {
  _SeekUpdatingProvider({required SongInfo songInfo}) : super(songInfo: songInfo);

  @override
  Future<void> seek(Duration position) async {
    final s = songInfo;
    if (s == null) return;
    setSongInfo(
      SongInfo(
        track: s.track,
        isPlaying: s.isPlaying,
        position: position.inMilliseconds,
        duration: s.duration,
      ),
    );
  }
}

class _RecordingLibraryController extends LibraryController {
  _RecordingLibraryController({required super.libraryBrowser, required super.libraryService});

  @override
  Future<void> loadFolder(String path) async {
    currentPath = path;
    notifyListeners();
  }
}

Future<void> _capturePng({
  required WidgetTester tester,
  required GlobalKey repaintBoundaryKey,
  required String fileName,
}) async {
  final ro = repaintBoundaryKey.currentContext!.findRenderObject();
  expect(ro, isA<RenderRepaintBoundary>());
  final boundary = ro as RenderRepaintBoundary;

  await tester.pump();

  final image = await boundary.toImage(pixelRatio: 1.0);
  final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
  image.dispose();
  final png = byteData?.buffer.asUint8List();
  expect(png, isNotNull);

  final outPath = '.tmp/$fileName.png';
  await File(outPath).writeAsBytes(png!);
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    SettingsService().immersiveNotifier.value = false;
    SettingsService().transportPositionNotifier.value = TransportPosition.bottom;
    SettingsService().browserPresentationNotifier.value =
        SettingsService.defaultBrowserPresentation;
  });

  testWidgets('Linux: swipe-to-seek feedback renders into bottom crumb row',
      (tester) async {
    await tester.binding.setSurfaceSize(const Size(800, 1600));

    final track = AudioTrack(
      path: '/fixture/track.mp3',
      title: 'Fixture Track',
      artist: 'Fixture Artist',
    );
    const durationMs = 120000; // 2:00

    final provider = _SeekUpdatingProvider(
      songInfo: SongInfo(
        track: track,
        isPlaying: false,
        position: 0,
        duration: durationMs,
      ),
    );

    final libraryController = _RecordingLibraryController(
      libraryBrowser: LibraryBrowser(supportedExtensions: const {'mp3'}),
      libraryService: LibraryService(),
    )
      ..hasPermission = true
      ..currentPath = '/music/parent-folder';

    final boundaryKey = GlobalKey();

    await tester.pumpWidget(
      ChangeNotifierProvider(
        create: (_) => provider,
        child: MaterialApp(
          theme: ThemeData(
            extensions: const <ThemeExtension<dynamic>>[
              AppPalette(),
              AppTypography(),
            ],
          ),
          home: Scaffold(
            body: RepaintBoundary(
              key: boundaryKey,
              child: VoidScreen(
                config: const SpectrumScreenConfig(),
                settings: const SpectrumSettings(),
                libraryController: libraryController,
              ),
            ),
          ),
        ),
      ),
    );

    await tester.pump();

    // Drag across the hero gesture surface.
    final gestureFinder = find.byKey(HeroFeedbackSurface.seekGestureKey);
    expect(gestureFinder, findsOneWidget);

    final box = tester.renderObject<RenderBox>(gestureFinder);
    final dx = box.size.width * 0.25;
    final start = tester.getCenter(gestureFinder);

    final gesture = await tester.startGesture(start);
    await gesture.moveBy(Offset(dx, 0));
    await tester.pump();

    // During gesture: center HUD is hidden on Linux, crumb shows preview.
    expect(find.byKey(HeroFeedbackSurface.seekHudKey), findsNothing);
    expect(find.textContaining('%'), findsOneWidget);
    await _capturePng(
      tester: tester,
      repaintBoundaryKey: boundaryKey,
      fileName: 'linux_swipe_seek_during',
    );

    await gesture.up();
    await tester.pumpAndSettle();

    // Post gesture: crumb returns to folder path.
    expect(find.text('/music/parent-folder'), findsOneWidget);

    await _capturePng(
      tester: tester,
      repaintBoundaryKey: boundaryKey,
      fileName: 'linux_swipe_seek_post',
    );

    await tester.binding.setSurfaceSize(null);
  });
}
